// site/lib/a2ui-catalog-selector.ts: the A2UI Catalog page's catalog selector model (T-0064). The options are the
// capability registry's catalog ids (`site/capability-registry.json`, generated by `npm run generate:registry`,
// ADR-0237), so a new catalog or persona appears after the registry regenerates, with no page edit. Each type of a
// non-default option is previewed by the first example seed that renders it (`seedsForCatalog`, the same function
// the every-catalog coverage gate reads), or names its documented exemption.
import { FLEET_CATALOG_ID } from '@agent-ui/a2ui/registry'
import { CATALOG_COVERAGE_EXEMPT, seedsForCatalog } from '@agent-ui/a2ui/examples'
import { REGISTRY, catalogIds, pageModel } from './capability-registry.ts'
import { typesInSeed } from './a2ui-catalog-tiers.ts'

/** Every catalog id the selector offers: agent-ui first, then the other bases, then the derived ids sorted. */
export const CATALOG_OPTIONS: readonly string[] = catalogIds(REGISTRY)

/** The `catalog` query parameter when it names an option, else the default agent-ui catalog. */
export function catalogFromSearch(search: string): string {
  const id = new URLSearchParams(search).get('catalog')
  return id !== null && CATALOG_OPTIONS.includes(id) ? id : FLEET_CATALOG_ID
}

/** The types one non-default option previews: a base lists all its types; a derived id lists only its persona
 *  fragment's own types (the base types stay browsable under the base option). */
export function typesFor(catalogId: string): readonly string[] {
  const model = pageModel(REGISTRY, catalogId)
  if (catalogId.includes('--')) return model.personaOnlyTypes
  return model.lines.map((line) => line.name).sort((a, b) => a.localeCompare(b))
}

/** The first seed for `catalogId`, in shelf order, whose `updateComponents` render `type`. */
export function exampleSeedFor(catalogId: string, type: string): ReturnType<typeof seedsForCatalog>[number] | undefined {
  return seedsForCatalog(catalogId).find((seed) => typesInSeed(seed).has(type))
}

/** Why `type` has no seed under `catalogId`, when the coverage gate's allowlist says so. */
export function exemptionFor(catalogId: string, type: string): string | undefined {
  return CATALOG_COVERAGE_EXEMPT[catalogId]?.[type]
}
